#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {        // drzewo: n-1 krawędzi
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    // BFS od korzenia 1 — iteracyjnie, więc bezpieczne nawet dla n = 10^6
    vector<int> par(n + 1, 0), depth(n + 1, 0), sz(n + 1, 1), order;
    order.reserve(n);
    queue<int> q;
    q.push(1);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        order.push_back(v);
        for (int u : g[v])
            if (u != par[v]) {                // w drzewie wystarczy pominąć rodzica
                par[u] = v;
                depth[u] = depth[v] + 1;
                q.push(u);
            }
    }
    // rozmiary poddrzew: od najgłębszych (koniec kolejności BFS) do korzenia
    for (int i = n - 1; i > 0; i--) sz[par[order[i]]] += sz[order[i]];
    int liscie = 0;
    for (int v = 1; v <= n; v++) {
        cout << v << ' ' << par[v] << ' ' << depth[v] << ' ' << sz[v] << '\n';
        if (sz[v] == 1) liscie++;           // brak dzieci = liść
    }
    cout << "liście: " << liscie << '\n';
}

const int MAXN = 200005;
vector<int> g[MAXN];
int par[MAXN], dep[MAXN], sz[MAXN];

void dfs(int v, int p) {          // wywołanie: dfs(1, 0)
    par[v] = p;
    sz[v] = 1;
    for (int u : g[v]) {
        if (u == p) continue;     // nie wracamy do rodzica
        dep[u] = dep[v] + 1;
        dfs(u, v);
        sz[v] += sz[u];           // po powrocie z dziecka znamy jego rozmiar
    }
}

