#include <bits/stdc++.h>
using namespace std;

int n;
vector<long long> bit;                    // Fenwick na pozycjach 1..n
void add(int i, long long x) { for (; i <= n; i += i & -i) bit[i] += x; }
long long sum(int i) { long long s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> n >> q;
    vector<long long> a(n + 1);
    for (int i = 1; i <= n; i++) cin >> a[i];
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int x, y;
        cin >> x >> y;
        g[x].push_back(y);
        g[y].push_back(x);
    }
    // Iteracyjny preorder: zdejmujemy v, nadajemy tin, wrzucamy dzieci.
    // Poddrzewo v jest przetwarzane w całości, zanim stos wróci poniżej v -> przedziały są spójne.
    vector<int> tin(n + 1), tout(n + 1), par(n + 1, 0), order, st = {1};
    int timer = 0;
    while (!st.empty()) {
        int v = st.back(); st.pop_back();
        tin[v] = ++timer;
        order.push_back(v);
        for (int u : g[v]) if (u != par[v]) { par[u] = v; st.push_back(u); }
    }
    vector<int> sz(n + 1, 1);
    for (int i = n - 1; i > 0; i--) sz[par[order[i]]] += sz[order[i]];
    for (int v = 1; v <= n; v++) tout[v] = tin[v] + sz[v] - 1;

    bit.assign(n + 1, 0);
    for (int v = 1; v <= n; v++) add(tin[v], a[v]);
    while (q--) {
        int t, v;
        cin >> t >> v;
        if (t == 1) {                      // 1 v x : ustaw wartość v na x
            long long x;
            cin >> x;
            add(tin[v], x - a[v]);
            a[v] = x;
        } else {                           // 2 v : suma w poddrzewie v
            cout << sum(tout[v]) - sum(tin[v] - 1) << '\n';
        }
    }
}

const int MAXN = 200005;
vector<int> g[MAXN];
int tin[MAXN], tout[MAXN], timer_ = 0;
int kto[MAXN];                     // kto[t] = wierzchołek o numerze t (odwrotność tin)

void dfs(int v, int p) {
    tin[v] = ++timer_;
    kto[tin[v]] = v;
    for (int u : g[v]) if (u != p) dfs(u, v);
    tout[v] = timer_;              // ostatni numer w poddrzewie v
}
bool przodek(int v, int u) {       // czy v jest przodkiem u (lub v == u)
    return tin[v] <= tin[u] && tin[u] <= tout[v];
}

