#include <bits/stdc++.h>
using namespace std;

int n;
vector<vector<int>> g;

// BFS z s: zwraca najdalszy wierzchołek, wypełnia dist i par
int bfs(int s, vector<int>& dist, vector<int>& par) {
    dist.assign(n + 1, -1);
    par.assign(n + 1, 0);
    queue<int> q;
    dist[s] = 0;
    q.push(s);
    int far = s;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        if (dist[v] > dist[far]) far = v;
