        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
        deg[a]++; deg[b]++;
    }
    vector<int> leaves;
    for (int v = 1; v <= n; v++) if (deg[v] <= 1) leaves.push_back(v);
    int pozostalo = n;
    while (pozostalo > 2) {                  // obcinamy całą warstwę liści naraz
        pozostalo -= leaves.size();
        vector<int> nowe;
        for (int v : leaves)
            for (int u : g[v])
                if (--deg[u] == 1) nowe.push_back(u);
        leaves = nowe;
    }
    sort(leaves.begin(), leaves.end());
    for (int v : leaves) cout << v << ' ';  // 1 albo 2 środki
    cout << '\n';
}

