#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;
int key_[MAXN], L[MAXN], R[MAXN], cnt = 0;    // węzły 1..cnt, 0 = brak syna

int nowy(int k) { key_[++cnt] = k; L[cnt] = R[cnt] = 0; return cnt; }

int root = 0;
void insert(int k) {                         // iteracyjnie: bez rekurencji na wysokim drzewie
    if (!root) { root = nowy(k); return; }
    int v = root;
    while (true) {
        if (k == key_[v]) return;            // duplikaty pomijamy
        int& nxt = (k < key_[v]) ? L[v] : R[v];
        if (!nxt) { nxt = nowy(k); return; }
        v = nxt;
    }
}
void pre(int v)  { if (!v) return; cout << key_[v] << ' '; pre(L[v]); pre(R[v]); }
void in(int v)   { if (!v) return; in(L[v]); cout << key_[v] << ' '; in(R[v]); }
void post(int v) { if (!v) return; post(L[v]); post(R[v]); cout << key_[v] << ' '; }
int height(int v) { return v ? 1 + max(height(L[v]), height(R[v])) : 0; }   // liczba poziomów

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) { int x; cin >> x; insert(x); }
    in(root);   cout << '\n';
    pre(root);  cout << '\n';
    post(root); cout << '\n';
    queue<int> q;                            // level order = BFS
    if (root) q.push(root);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        cout << key_[v] << ' ';
        if (L[v]) q.push(L[v]);
        if (R[v]) q.push(R[v]);
    }
    cout << '\n' << height(root) << '\n';
}

// Szukanie w BST, minimum, następnik (najmniejszy klucz > k)
const int MAXN = 200005;
int key_[MAXN], L[MAXN], R[MAXN];
bool znajdz(int v, int k) {
    while (v && key_[v] != k) v = (k < key_[v]) ? L[v] : R[v];
    return v != 0;
}
int minimum(int v) { while (L[v]) v = L[v]; return key_[v]; }
int nastepnik(int root, int k) {      // -1 gdy brak
    int v = root, res = -1;
    while (v) {
        if (key_[v] > k) { res = key_[v]; v = L[v]; }
        else v = R[v];
    }
    return res;
}

