#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000005;
int h[MAXN], sz = 0;                  // min-kopiec w h[1..sz]

void push(int x) {
    h[++sz] = x;
    int v = sz;
    while (v > 1 && h[v / 2] > h[v]) {    // sift up
        swap(h[v / 2], h[v]);
        v /= 2;
    }
}
void siftDown(int v) {
    while (2 * v <= sz) {
        int c = 2 * v;                         // lewy syn
        if (c + 1 <= sz && h[c + 1] < h[c]) c++;   // mniejszy z synów
        if (h[v] <= h[c]) break;
        swap(h[v], h[c]);
        v = c;
    }
}
int pop() {                           // zdejmuje i zwraca minimum
    int res = h[1];
    h[1] = h[sz--];
    siftDown(1);
    return res;
}

int main() {
    int q;
    cin >> q;
    while (q--) {
        int t;
        cin >> t;
        if (t == 1) { int x; cin >> x; push(x); }          // 1 x : dodaj
        else if (t == 2) cout << pop() << '\n';            // 2   : zdejmij minimum
        else cout << h[1] << '\n';                         // 3   : podejrzyj minimum
    }
}

// heapify: budowa kopca z całej tablicy w O(n) — sift down od ostatniego węzła wewnętrznego
const int MAXN = 1000005;
int h[MAXN], sz;
void siftDown(int v) {
    while (2 * v <= sz) {
        int c = 2 * v;
        if (c + 1 <= sz && h[c + 1] < h[c]) c++;
        if (h[v] <= h[c]) break;
        swap(h[v], h[c]);
        v = c;
    }
}
void heapify(int n) {
    sz = n;
    for (int v = n / 2; v >= 1; v--) siftDown(v);
}

