#include <bits/stdc++.h>
using namespace std;

const int LOG = 18;                      // 2^18 > 2*10^5

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> val(n + 1);
    for (int i = 1; i <= n; i++) cin >> val[i];
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    // BFS od korzenia 1: rodzic, głębokość, prefiks
    vector<int> dep(n + 1, 0), order;
    vector<vector<int>> up(LOG, vector<int>(n + 1, 1));   // up[k][v] = przodek o 2^k wyżej
    vector<long long> pre(n + 1, 0);
    vector<bool> vis(n + 1, false);
    queue<int> qu;
    qu.push(1); vis[1] = true; pre[1] = val[1];
    while (!qu.empty()) {
        int v = qu.front(); qu.pop();
        order.push_back(v);
        for (int u : g[v]) if (!vis[u]) {
            vis[u] = true;
            up[0][u] = v;
            dep[u] = dep[v] + 1;
            pre[u] = pre[v] + val[u];
            qu.push(u);
        }
    }
    for (int k = 1; k < LOG; k++)
        for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
    auto lca = [&](int a, int b) {
        if (dep[a] < dep[b]) swap(a, b);
        int diff = dep[a] - dep[b];
        for (int k = 0; k < LOG; k++) if (diff >> k & 1) a = up[k][a];
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--)
            if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
        return up[0][a];
    };
    while (q--) {
        int u, v;
        cin >> u >> v;
        int l = lca(u, v);
        cout << pre[u] + pre[v] - 2 * pre[l] + val[l] << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

// Zapytania: "1 v x" — ustaw wartość v na x; "2 u v" — suma na ścieżce u–v.
// Zmiana val[v] o d zmienia pre[] o d w CAŁYM poddrzewie v -> Fenwick: dodaj na [tin, tout], punktowo czytaj.
const int LOG = 18;
int n;
vector<long long> bit;
void add(int i, long long x) { for (; i <= n; i += i & -i) bit[i] += x; }
long long pref(int i) { long long s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }

int main() {
    int q;
    cin >> n >> q;
    vector<long long> val(n + 1);
    for (int i = 1; i <= n; i++) cin >> val[i];
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> dep(n + 1, 0), tin(n + 1), tout(n + 1), order, st = {1}, sz(n + 1, 1);
    vector<vector<int>> up(LOG, vector<int>(n + 1, 1));
    up[0][1] = 0;
    int timer = 0;
    while (!st.empty()) {                       // iteracyjny preorder
        int v = st.back(); st.pop_back();
        tin[v] = ++timer;
        order.push_back(v);
        for (int u : g[v]) if (u != up[0][v]) { up[0][u] = v; dep[u] = dep[v] + 1; st.push_back(u); }
    }
    up[0][1] = 1;
    for (int i = n - 1; i > 0; i--) sz[up[0][order[i]]] += sz[order[i]];
    for (int v = 1; v <= n; v++) tout[v] = tin[v] + sz[v] - 1;
    for (int k = 1; k < LOG; k++)
        for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
    auto lca = [&](int a, int b) {
        if (dep[a] < dep[b]) swap(a, b);
        for (int k = LOG - 1; k >= 0; k--) if (dep[a] - (1 << k) >= dep[b]) a = up[k][a];
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
        return up[0][a];
    };
    bit.assign(n + 2, 0);
    auto dodajPoddrzewo = [&](int v, long long d) { add(tin[v], d); add(tout[v] + 1, -d); };
    for (int v = 1; v <= n; v++) dodajPoddrzewo(v, val[v]);
    auto P = [&](int v) { return pref(tin[v]); };      // aktualne pre[v]
    while (q--) {
        int t, a;
        long long b;
        cin >> t >> a >> b;
        if (t == 1) { dodajPoddrzewo(a, b - val[a]); val[a] = b; }
        else {
            int u = a, v = (int)b, l = lca(u, v);
            cout << P(u) + P(v) - 2 * P(l) + val[l] << '\n';
        }
    }
}

